MATCH (:PlantItem {tag: 'D-3001'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (f:PlantItem {tag: 'F-3901'})-[:send_to]-(v:OperatedValve)<-[:control]-(a)<-[:send_signal_to]-(c:ProcessControlFunction)
RETURN DISTINCT c.loop_tag AS loop_tag
ORDER BY loop_tag;

MATCH (s:PlantItem {tag: 'P-1503'}), (e:PlantItem {tag: 'GTV-15020'})
MATCH p = shortestPath((s)-[:send_to*]->(e))
RETURN [n IN nodes(p) WHERE 'Equipment' IN labels(n) OR any(label IN labels(n) WHERE label CONTAINS 'Valve') | n.tag] AS path_tags;

MATCH (item:PlantItem {tag: "P-4401"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (source:PlantItem {tag: "EJ-1801B"})-[:send_to*1..]->(target:PlantItem {tag: "P-5201B"})
RETURN source.tag AS source_tag, target.tag AS target_tag
LIMIT 1;

MATCH (item:PlantItem {tag: "V-1402"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (source:PlantItem)-[:send_to*1..]->(:PlantItem {tag: 'P-101'})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "P-1601A"})
WHERE NOT EXISTS {
  MATCH ()-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
ORDER BY tag

MATCH (e:Equipment {tag: "E-1403"})-[:send_to]-(v:PlantItem)<-[:control]-(a:ActuatingFunction)<-[:send_signal_to]-(c:ProcessControlFunction)
RETURN DISTINCT c.loop_tag AS loop_tag
ORDER BY loop_tag;

MATCH (item:PlantItem {tag: "EA-3801"})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'H-401'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (s:PlantItem {tag: "E-1301"}), (d:PlantItem {tag: "D-1301"}), p = (s)-[:send_to*]->(d)
RETURN s.tag AS source_tag, d.tag AS destination_tag, [n IN nodes(p) | n.tag] AS path_tags
LIMIT 1;

MATCH (i:PlantItem:AngleValve)
WHERE i.unit_id = '18'
RETURN count(i) AS angle_valve_count, collect(i.tag) AS tags;

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "E-302"})
WHERE NOT EXISTS { MATCH (:PlantItem)-[:send_to]->(source) }
RETURN DISTINCT source.tag AS tag

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: 'E-301'})
WHERE NOT EXISTS { MATCH ()-[:send_to]->(source) }
RETURN DISTINCT source.tag AS tag
ORDER BY tag;

MATCH p = shortestPath(
  (s:PlantItem {tag: 'V-5001'})-[:send_to*]->(t:PlantItem {tag: 'P-3101C'})
)
RETURN [n IN nodes(p) | n.tag] AS path_tags;

MATCH (source:PlantItem)-[:send_to*1..]->(:PlantItem {tag: 'V-501'})
WHERE NOT EXISTS {
  MATCH (source)<-[:send_to]-()
}
RETURN DISTINCT source.tag AS tag

MATCH p = (start:PlantItem {tag: 'M-4902'})-[:send_to*]->(finish:PlantItem {tag: 'E-402'})
WITH p, ['AngleBallValve', 'AngleGlobeValve', 'AnglePlugValve', 'AngleValve', 'BallValve', 'BreatherValve', 'ButterflyValve', 'CheckValve', 'GateValve', 'GlobeCheckValve', 'GlobeValve', 'NeedleValve', 'OperatedValve', 'PlugValve', 'SafetyValveOrFitting', 'SpringLoadedAngleGlobeSafetyValve', 'SpringLoadedGlobeSafetyValve', 'StraightwayValve', 'SwingCheckValve'] AS valveLabels
RETURN [n IN nodes(p) WHERE 'Equipment' IN labels(n) OR any(label IN labels(n) WHERE label IN valveLabels) | n.tag] AS equipment_and_valve_tags;
